"use client"

import * as React from "react"
import * as TooltipPrimitive from "@radix-ui/react-tooltip"

import { cn } from "@/lib/utils"

/** Holds a still pointer for 400ms before whispering; focus shows it at once. */
function TooltipProvider({ delayDuration = 400, ...props }: React.ComponentProps<typeof TooltipPrimitive.Provider>) {
  return <TooltipPrimitive.Provider data-slot="tooltip-provider" delayDuration={delayDuration} {...props} />
}

function Tooltip(props: React.ComponentProps<typeof TooltipPrimitive.Root>) {
  return (
    <TooltipProvider>
      <TooltipPrimitive.Root data-slot="tooltip" {...props} />
    </TooltipProvider>
  )
}

function TooltipTrigger(props: React.ComponentProps<typeof TooltipPrimitive.Trigger>) {
  return <TooltipPrimitive.Trigger data-slot="tooltip-trigger" {...props} />
}

type TooltipContentProps = React.ComponentProps<typeof TooltipPrimitive.Content> & { variant?: "whisper" | "initials" | "beside" }

/**
 * A whisper. Keep it to a few words; it names, it doesn't explain. whisper (the default): in
 * parentheses above the thing it names. initials: the same, with the letters the control shows
 * marked in the words they come from (wrap each in <b>). beside: on the control's own line, after it,
 * on a hairline.
 */
function TooltipContent(props: TooltipContentProps) {
  return (
    <TooltipPrimitive.Portal>
      <Placed {...props} />
    </TooltipPrimitive.Portal>
  )
}

// Beside reads on from the control, so it sits at the line's end: the right, or the left on a
// right-to-left page. The portal mounts this only once open, in the browser, so the direction is read
// fresh each time and can't disagree with the server's (closed, empty) render.
// ponytail: reads the page's direction, not the trigger's; pass side for a mixed-direction page.
function Placed({ className, variant = "whisper", side, sideOffset = variant === "beside" ? 10 : 8, ...props }: TooltipContentProps) {
  const rtl = variant === "beside" && !side && getComputedStyle(document.body).direction === "rtl"
  return (
    <TooltipPrimitive.Content
      data-slot="tooltip-content"
      data-variant={variant === "whisper" ? undefined : variant}
      side={side ?? (variant === "beside" ? (rtl ? "left" : "right") : "top")}
      sideOffset={sideOffset}
      className={cn("db-tip-text", className)}
      {...props}
    />
  )
}

export { Tooltip, TooltipTrigger, TooltipContent, TooltipProvider }

@layer components {
  /* ── db-tip ── tooltip: a whisper in parentheses above the thing it names. The parentheses are set
     thin and taller than the words, as 20(25) sets them round its figures, so the whisper reads as
     an aside held apart from the page. Radix positions it (side top, 8px off) and holds it for a
     still pointer; focus shows it at once and Escape puts it away. */
  .db-tip-text {
    z-index: 50; width: max-content; max-width: 32ch; padding: 0.1em 0.35em; background: var(--db-paper);
    font-family: var(--db-voice); font-size: var(--db-pp); line-height: var(--db-pp-lh); color: var(--db-graphite); text-align: center; white-space: normal;
    animation: db-tip-in var(--db-moderato) var(--db-exhale);
  }
  .db-tip-text::before { content: "(" / ""; }
  .db-tip-text::after { content: ")" / ""; }
  .db-tip-text::before, .db-tip-text::after { font-size: 1.6em; font-weight: 200; line-height: 0; vertical-align: -0.12em; color: var(--db-ink); }
  .db-tip-text::before { margin-inline-end: 0.08em; }
  .db-tip-text::after { margin-inline-start: 0.08em; }
  .db-tip-text[data-state="closed"] { animation: db-tip-out var(--db-allegro) var(--db-breath) forwards; }
  @keyframes db-tip-in { from { opacity: 0; translate: 0 0.3em; } }
  @keyframes db-tip-out { to { opacity: 0; } }

  /* ── initials ── for a key or an abbreviation: the letters the control shows are found in the
     whisper's words and reversed out of the ink, as "the uncreative" reverses part of its word, so
     you can see where G, or CMYK, comes from. Mark each with <b>. The initials land first and the
     words are written in around them. */
  .db-tip-text[data-variant="initials"] b { display: inline-block; padding-inline: 0.1em; font-weight: 700; background: var(--db-ink); color: var(--db-paper); }
  .db-tip-text[data-variant="initials"][data-state="delayed-open"],
  .db-tip-text[data-variant="initials"][data-state="instant-open"] { animation: db-tip-write var(--db-moderato) var(--db-exhale) var(--db-allegro) backwards; }
  .db-tip-text[data-variant="initials"]:is([data-state="delayed-open"], [data-state="instant-open"]) b { animation: db-tip-land var(--db-moderato) var(--db-spiccato) backwards; }
  @keyframes db-tip-write { from { color: transparent; } }
  @keyframes db-tip-land { from { opacity: 0; scale: 0.4; } }

  /* ── beside ── the whisper on the control's own line, after it, on a hairline that runs from the
     control: the small notes of "It has to be design." hung beside the headline. No parentheses: the
     line holds it apart. The line always faces the control, whichever side Radix settles on. */
  .db-tip-text[data-variant="beside"] { display: flex; align-items: center; gap: var(--db-space-2); max-width: 28ch; padding-inline: 0 0.35em; text-align: start; }
  .db-tip-text[data-variant="beside"]::after { content: none; }
  .db-tip-text[data-variant="beside"]::before { content: ""; flex: none; width: var(--db-space-5); height: var(--db-hairline); margin: 0; background: var(--db-ink); }
  .db-tip-text[data-variant="beside"][data-side="left"] { flex-direction: row-reverse; padding-inline: 0.35em 0; }
  .db-tip-text[data-variant="beside"][data-side="left"]:is([dir="rtl"], [dir="rtl"] *) { flex-direction: row; padding-inline: 0.35em 0; }
  .db-tip-text[data-variant="beside"][data-side="right"]:is([dir="rtl"], [dir="rtl"] *) { flex-direction: row-reverse; padding-inline: 0 0.35em; }
  .db-tip-text[data-variant="beside"]:is([data-side="top"], [data-side="bottom"])::before { display: none; } /* flipped above or below: no line to run along */
  /* Reach: the hairline draws out from the control, then the words arrive at its end. */
  .db-tip-text[data-variant="beside"]:is([data-state="delayed-open"], [data-state="instant-open"]) { animation: db-tip-write var(--db-moderato) var(--db-exhale) var(--db-allegro) backwards; }
  .db-tip-text[data-variant="beside"]:is([data-state="delayed-open"], [data-state="instant-open"])::before { animation: db-tip-reach var(--db-moderato) var(--db-exhale) backwards; }
  .db-tip-text[data-variant="beside"][data-side="right"]::before { transform-origin: 0 50%; }
  .db-tip-text[data-variant="beside"][data-side="left"]::before { transform-origin: 100% 50%; }
  @keyframes db-tip-reach { from { scale: 0 1; } }

  @media (forced-colors: active) {
    .db-tip-text[data-variant="beside"]::before { forced-color-adjust: none; background: CanvasText; }
    .db-tip-text[data-variant="initials"] b { forced-color-adjust: none; background: CanvasText; color: Canvas; }
  }
}
